const grade = $input.first().json;
const draft = grade.choices && grade.choices[0] && grade.choices[0].message ? grade.choices[0].message.content : '';
if (!draft) return [{ json: { verifyModel: null, draft: '', messages: [], error: 'Grading failed on the free and the paid model' } }];
const context = $('Build request').first().json.contextText;
const user = context + '

Draft grading (JSON):
' + draft;
const messages = [{ role: 'system', content: "You are a second examiner doing the final check of a grading for the Dutch Inburgering A2 speaking exam. You receive the question context, the transcript and a DRAFT grading in JSON.

Check the draft and return a corrected version in the same JSON shape, JSON only, no markdown:
- verdict: "no-answer" when the transcript is empty; otherwise "answered" or "incorrect". Make sure the verdict matches the transcript and the task.
- mistakes: keep only real grammar or word-choice errors. Each "original" must be an exact fragment of the transcript. Each "correction" must be correct Dutch and as minimal as possible. Remove invalid items and add missing important ones.
- proposedAnswer: empty when the verdict is "answered"; otherwise a correct, short A2 Dutch answer covering every key point.
- score: 0 for "no-answer", 6 or more for "answered", and consistent with the mistakes otherwise.
- Keep the strategies the candidate used (parrot, denial, Makhmud, universal answers) as valid when the task is still addressed.
The first examiner saw the exam pictures; you did not. Do not change what a proposed answer says is on the pictures. Keep the feedback in English. Fields: transcript, verdict, score, completed, strengths, missingPoints, mistakes, proposedAnswer, feedback." }, { role: 'user', content: user }];
return [{ json: { verifyModel: 'thinkingmachines/inkling:free', draft, messages } }];

const reply = $input.first().json;
const fromModel = reply.choices && reply.choices[0] && reply.choices[0].message ? reply.choices[0].message.content : '';
const prepared = $('Prepare verify').first().json;
const draft = prepared.draft || '';
const pick = (raw) => { const start = raw.indexOf('{'); const end = raw.lastIndexOf('}'); if (start === -1 || end <= start) throw new Error('no JSON'); return JSON.parse(raw.slice(start, end + 1)); };
let result;
try { result = pick(fromModel); } catch (error) { try { result = pick(draft); } catch (error2) { result = { error: prepared.error || 'The model returned no usable answer.', transcript: '', verdict: 'incorrect', score: 0, completed: false, strengths: [], missingPoints: [], mistakes: [], proposedAnswer: '', feedback: '' }; } }
if ($('Build request').first().json.noInput) { result.transcript = ''; result.verdict = 'no-answer'; result.score = 0; result.completed = false; }
return [{ json: result }];
